#!/usr/bin/env bash
# Regression test for tests/check_scratch_refs.sh. The gate's whole value is
# its scan boundary: code that a fresh clone runs must fail on a .scratch/
# citation, while the harness scripts that drive the tracker as a mechanism,
# the vendored trees, and the docs/ prose index must stay silent — one
# over-broad allowlist entry and the gate stops biting, one too narrow and
# the harness starts failing its own wiring. Contract pinned here.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'check_scratch_refs.sh self-test needs a git checkout\n' >&2
    exit 1
}
check=$root/tests/check_scratch_refs.sh
if [ ! -f "$check" ]; then
    printf 'missing gate: %s\n' "$check" >&2
    exit 1
fi

# Not a bare /tmp: MSYS child shells default TMP/TEMP to /tmp, and native
# git.exe then maps a /tmp argument to C:\tmp while bash sees %TEMP%.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -u "$USERPROFILE")
else
    tmpbase=${TMPDIR:-/tmp}
fi
tmp=$(mktemp -d "$tmpbase/pime-scratch-refs-selftest.XXXXXX")
sandbox=$tmp/repo
mkdir -p "$sandbox/tests" "$sandbox/python/python3" "$sandbox/docs"

cleanup() {
    rm -rf "$tmp"
}
trap cleanup EXIT

git -C "$sandbox" init -q >/dev/null || {
    printf 'git init failed in sandbox\n' >&2
    exit 1
}

failures=0

# expect <want> <name> — runs the gate in the sandbox and matches output.
expect() {
    local want=$1 name=$2 out got
    out=$(cd "$sandbox" && bash "$check" 2>&1)
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s (exit %s, want %s)\n%s\n' "$name" "$got" "$want" "$out"
        failures=$((failures + 1))
    fi
}

expect_named() {
    local want=$1 name=$2 needle=$3 out got
    out=$(cd "$sandbox" && bash "$check" 2>&1)
    got=$?
    if [ "$got" -ne "$want" ] || ! printf '%s\n' "$out" | grep -qF "$needle"; then
        printf 'FAIL  %s (exit %s, want %s; want line %s)\n%s\n' \
            "$name" "$got" "$want" "$needle" "$out"
        failures=$((failures + 1))
    fi
}

# A test that cites the excluded tracker must fail and name the file: that
# dead link is the incident this gate was born from.
printf '# See .scratch/upstream-bug-backlog/ for the audit.\nx = 1\n' > "$sandbox/tests/test_cited.py"
git -C "$sandbox" add tests/test_cited.py
expect_named 1 'test citing .scratch fails and is named' 'tests/test_cited.py'

# Removing the citation clears the gate again.
printf 'x = 1\n' > "$sandbox/tests/test_cited.py"
git -C "$sandbox" add tests/test_cited.py
expect 0 'cleaned citation passes'

# Harness scripts that drive the tracker are mechanism, not dead links.
printf '#!/usr/bin/env bash\n# reads .scratch/upstream-bug-backlog/issues\n' > "$sandbox/tests/check_watcher.sh"
printf '#!/usr/bin/env bash\n# walks .scratch for the layout gate\n' > "$sandbox/tests/run_watcher.sh"
git -C "$sandbox" add tests/check_watcher.sh tests/run_watcher.sh
expect 0 'harness allowlist stays silent'

# The vendored interpreter tree ships its own prose.
printf '# mentions .scratch/ somewhere\n' > "$sandbox/python/python3/doc.py"
git -C "$sandbox" add python/python3/doc.py
expect 0 'vendored tree stays silent'

# docs/ is the tracker index; prose citations there are legal.
printf 'Tickets live under .scratch/<effort>/issues/.\n' > "$sandbox/docs/issue-tracker.md"
git -C "$sandbox" add docs/issue-tracker.md
expect 0 'docs prose citation is legal'

# Outside a git checkout the gate is not applicable, not a failure.
nowork=$tmp/nowork
mkdir -p "$nowork"
out=$(cd "$nowork" && bash "$check" 2>&1)
got=$?
if [ "$got" -ne 125 ]; then
    printf 'FAIL  outside checkout skips (exit %s, want 125)\n%s\n' "$got" "$out"
    failures=$((failures + 1))
fi

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
